import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../api/axiosInstance';
import styles from './Dashboard.module.css';

/* ─── Static data (replace with API calls as your backend grows) ─── */

const STORES = [
  { id: 1, name: 'D-Mart',       dist: '0.4 km', color: '#2563EB', initials: 'DM', timing: '9AM–9PM',   rating: '4.3' },
  { id: 2, name: 'Reliance Fresh',dist: '0.8 km', color: '#059669', initials: 'RF', timing: '10AM–10PM', rating: '4.1' },
  { id: 3, name: 'More Retail',  dist: '1.2 km', color: '#7C3AED', initials: 'MR', timing: '9AM–8PM',   rating: '3.9' },
  { id: 4, name: 'Star Bazaar',  dist: '1.9 km', color: '#DC2626', initials: 'SB', timing: '10AM–9PM',  rating: '4.5' },
  { id: 5, name: "Spencer's",    dist: '2.3 km', color: '#D97706', initials: 'SP', timing: '9AM–9PM',   rating: '4.0' },
];

const CATEGORIES = [
  { id: 'fruits',      label: 'Fruits & Veg',   icon: '🥦', count: '240+ items', bg: '#EAF3DE' },
  { id: 'dairy',       label: 'Dairy',           icon: '🥛', count: '80+ items',  bg: '#E6F1FB' },
  { id: 'snacks',      label: 'Snacks',          icon: '🍿', count: '320+ items', bg: '#FAEEDA' },
  { id: 'personal',    label: 'Personal Care',   icon: '🧴', count: '180+ items', bg: '#FBEAF0' },
  { id: 'cleaning',    label: 'Household',       icon: '🧹', count: '150+ items', bg: '#E1F5EE' },
  { id: 'electronics', label: 'Electronics',     icon: '📱', count: '90+ items',  bg: '#EEEDFE' },
  { id: 'bakery',      label: 'Bakery',          icon: '🍞', count: '60+ items',  bg: '#FAEEDA' },
  { id: 'beverages',   label: 'Beverages',       icon: '🧃', count: '200+ items', bg: '#EAF3DE' },
];

const ALL_ITEMS = {
  fruits: [
    { name: 'Organic Tomatoes',  brand: 'Farm Fresh',      price: '₹49',    status: 'in',  emoji: '🍅' },
    { name: 'Alphonso Mangoes',  brand: 'Maharashtra',     price: '₹199',   status: 'low', emoji: '🥭' },
    { name: 'Baby Spinach',      brand: "Nature's Basket", price: '₹35',    status: 'in',  emoji: '🥬' },
    { name: 'Watermelon',        brand: 'Local Farm',      price: '₹89',    status: 'out', emoji: '🍉' },
  ],
  dairy: [
    { name: 'Amul Gold Milk',    brand: 'Amul',            price: '₹65',    status: 'in',  emoji: '🥛' },
    { name: 'Greek Yogurt',      brand: 'Epigamia',        price: '₹85',    status: 'low', emoji: '🫙' },
    { name: 'Paneer Fresh',      brand: 'Mother Dairy',    price: '₹90',    status: 'in',  emoji: '🧀' },
    { name: 'Butter Unsalted',   brand: 'Amul',            price: '₹55',    status: 'out', emoji: '🧈' },
  ],
  snacks: [
    { name: "Lay's Classic",     brand: 'PepsiCo',         price: '₹20',    status: 'in',  emoji: '🥔' },
    { name: 'Bingo Mad Angles',  brand: 'ITC',             price: '₹30',    status: 'in',  emoji: '🌽' },
    { name: "Haldiram's Mix",    brand: "Haldiram's",      price: '₹55',    status: 'low', emoji: '🍿' },
    { name: 'Oreo Cookies',      brand: 'Mondelez',        price: '₹45',    status: 'out', emoji: '🍪' },
  ],
  personal: [
    { name: 'Dove Body Wash',    brand: 'HUL',             price: '₹199',   status: 'in',  emoji: '🧴' },
    { name: 'Colgate Max Fresh', brand: 'Colgate',         price: '₹89',    status: 'in',  emoji: '🦷' },
    { name: 'Garnier Facewash',  brand: "L'Oreal",         price: '₹149',   status: 'low', emoji: '✨' },
    { name: 'Parachute Hair Oil',brand: 'Marico',          price: '₹85',    status: 'in',  emoji: '💆' },
  ],
  cleaning: [
    { name: 'Vim Dishwash Bar',  brand: 'HUL',             price: '₹42',    status: 'in',  emoji: '🫧' },
    { name: 'Harpic Power Plus', brand: 'Reckitt',         price: '₹99',    status: 'in',  emoji: '🚿' },
    { name: 'Lizol Surface Cleaner', brand: 'Colgate-P',   price: '₹149',   status: 'low', emoji: '🧹' },
    { name: 'Ariel Detergent',   brand: 'P&G',             price: '₹230',   status: 'out', emoji: '👕' },
  ],
  electronics: [
    { name: 'boAt Earbuds',      brand: 'boAt',            price: '₹1,299', status: 'in',  emoji: '🎧' },
    { name: 'Anchor USB Hub',    brand: 'Anchor',          price: '₹449',   status: 'in',  emoji: '🔌' },
    { name: 'Duracell AA 4pk',   brand: 'Duracell',        price: '₹149',   status: 'low', emoji: '🔋' },
    { name: 'Portronics Mouse',  brand: 'Portronics',      price: '₹699',   status: 'out', emoji: '🖱️' },
  ],
  bakery: [
    { name: 'Britannia Brown Bread', brand: 'Britannia',   price: '₹45',    status: 'in',  emoji: '🍞' },
    { name: 'Croissant Pack',    brand: 'Monginis',        price: '₹75',    status: 'in',  emoji: '🥐' },
    { name: 'Atta Whole Wheat',  brand: 'Aashirvaad',      price: '₹299',   status: 'low', emoji: '🌾' },
    { name: 'Cake Slice',        brand: 'Winkies',         price: '₹35',    status: 'out', emoji: '🍰' },
  ],
  beverages: [
    { name: 'Kinley Water 1L',   brand: 'Coca-Cola',       price: '₹20',    status: 'in',  emoji: '💧' },
    { name: 'Tropicana Orange',  brand: 'PepsiCo',         price: '₹65',    status: 'in',  emoji: '🍊' },
    { name: 'Red Bull 250ml',    brand: 'Red Bull',        price: '₹125',   status: 'low', emoji: '🔴' },
    { name: 'Nescafe Classic',   brand: 'Nestle',          price: '₹219',   status: 'out', emoji: '☕' },
  ],
};

const STATUS_META = {
  in:  { label: 'In Stock',    cls: 'badgeIn'  },
  low: { label: 'Low Stock',   cls: 'badgeLow' },
  out: { label: 'Out of Stock',cls: 'badgeOut' },
};

const FILTERS = ['All', 'In Stock', 'Low Stock', 'Out of Stock'];

/* ─── Helpers ─── */
function getFeatured() {
  return Object.values(ALL_ITEMS).flat().sort(() => Math.random() - 0.5).slice(0, 6);
}

/* ─── Sub-components ─── */

function StoreAvatar({ store }) {
  return (
      <div className={styles.storeAvatar} style={{ background: store.color }}>
        {store.initials}
      </div>
  );
}

function ItemCard({ item, added, onAdd }) {
  const s = STATUS_META[item.status];
  return (
      <div className={styles.itemCard}>
        <div className={styles.itemImg}>
          <span className={styles.itemEmoji}>{item.emoji}</span>
          <span className={`${styles.badge} ${styles[s.cls]}`}>{s.label}</span>
        </div>
        <div className={styles.itemBody}>
          <p className={styles.itemName}>{item.name}</p>
          <p className={styles.itemBrand}>{item.brand}</p>
          <div className={styles.itemFooter}>
            <span className={styles.itemPrice}>{item.price}</span>
            <button
                className={`${styles.addBtn} ${added ? styles.addBtnAdded : ''}`}
                onClick={() => onAdd(item.name)}
                aria-label={`${added ? 'Remove' : 'Add'} ${item.name}`}
                disabled={item.status === 'out'}
            >
              {added ? '✓' : '+'}
            </button>
          </div>
        </div>
      </div>
  );
}

/* ─── Main Dashboard ─── */

export default function Dashboard() {
  const { logout } = useAuth();
  const navigate   = useNavigate();

  /* backend state (kept from original) */
  const [apiStatus, setApiStatus] = useState('');

  /* store / category state */
  const [selectedStore, setSelectedStore] = useState(null);
  const [selectedCat,   setSelectedCat]   = useState(null);
  const [activeFilter,  setActiveFilter]  = useState('All');
  const [searchQuery,   setSearchQuery]   = useState('');

  /* items state */
  const [displayedItems, setDisplayedItems] = useState(getFeatured);
  const [cartItems,      setCartItems]      = useState(new Set());

  /* toast */
  const [toast, setToast] = useState('');
  const [toastVisible, setToastVisible] = useState(false);

  /* ── derived ── */
  const cartCount = cartItems.size;

  /* ── effects ── */
  useEffect(() => {
    // Optional: ping your backend welcome endpoint on mount
    api.get('/').then(res => setApiStatus(res.data)).catch(() => {});
  }, []);

  useEffect(() => {
    if (!selectedCat) return;
    const statusMap = { 'In Stock': 'in', 'Low Stock': 'low', 'Out of Stock': 'out' };
    const base = ALL_ITEMS[selectedCat] || [];
    setDisplayedItems(
        activeFilter === 'All' ? base : base.filter(i => i.status === statusMap[activeFilter])
    );
  }, [selectedCat, activeFilter]);

  /* ── handlers ── */
  function applyFilter(items, filter) {
    const map = { 'In Stock': 'in', 'Low Stock': 'low', 'Out of Stock': 'out' };
    setDisplayedItems(filter === 'All' ? items : items.filter(i => i.status === map[filter]));
  }

  function handleSelectStore(store) {
    setSelectedStore(store);
    showToast(`📍 Switched to ${store.name}`);
  }

  function handleSelectCat(cat) {
    setSelectedCat(cat);
    setActiveFilter('All');
  }

  function handleAddToCart(name) {
    setCartItems(prev => {
      const next = new Set(prev);
      if (next.has(name)) { next.delete(name); showToast(`Removed: ${name}`); }
      else                { next.add(name);    showToast(`🛒 Added: ${name}`); }
      return next;
    });
  }

  function handleSearch(e) {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    // Wire to your search API here; for now filter across all items
    const q = searchQuery.toLowerCase();
    const results = Object.values(ALL_ITEMS).flat().filter(
        i => i.name.toLowerCase().includes(q) || i.brand.toLowerCase().includes(q)
    );
    setSelectedCat(null);
    setDisplayedItems(results);
  }

  function handleLogout() {
    logout();
    navigate('/login');
  }

  function showToast(msg) {
    setToast(msg);
    setToastVisible(true);
    setTimeout(() => setToastVisible(false), 2200);
  }

  /* ── render ── */
  return (
      <div className={styles.page}>

        {/* ── Top Bar ── */}
        <header className={styles.topbar}>
          <div className={styles.logo}>
            Instore<span className={styles.logoAccent}>GO</span>
            <span className={styles.logoDot} />
          </div>

          <form className={styles.searchBar} onSubmit={handleSearch}>
            <span className={styles.searchIcon}>🔍</span>
            <input
                className={styles.searchInput}
                type="text"
                placeholder="Search items, stores, categories…"
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
            />
            <button className={styles.searchBtn} type="submit">Search</button>
          </form>

          <div className={styles.topRight}>
            <span className={styles.locationChip}>📍 Warangal</span>
            <button className={styles.logoutBtn} onClick={handleLogout}>Logout</button>
          </div>
        </header>

        {/* ── Hero / Store Selector ── */}
        <section className={styles.hero}>
          <div className={styles.heroInner}>
            <p className={styles.heroTag}>Check items before you step out</p>
            <h1 className={styles.heroTitle}>
              Pick a store, browse by <em className={styles.heroEm}>category</em>
            </h1>
            <p className={styles.heroSub}>
              Real-time availability at your nearest stores — no more wasted trips.
            </p>

            <p className={styles.storeLabel}>NEARBY STORES</p>
            <div className={styles.storeRow}>
              {STORES.map(s => (
                  <button
                      key={s.id}
                      className={`${styles.storePill} ${selectedStore?.id === s.id ? styles.storePillActive : ''}`}
                      onClick={() => handleSelectStore(s)}
                  >
                    <StoreAvatar store={s} />
                    <span className={styles.storeName}>{s.name}</span>
                    <span className={styles.storeDist}>{s.dist}</span>
                  </button>
              ))}
            </div>
          </div>
        </section>

        <main className={styles.main}>

          {/* ── Selected Store Info Bar ── */}
          {selectedStore && (
              <div className={styles.storeInfoBar}>
                <span className={styles.storeInfoIcon}>🏪</span>
                <div>
                  <strong>{selectedStore.name}</strong>
                  <span className={styles.storeInfoMeta}>
                &nbsp;· ⭐ {selectedStore.rating} · {selectedStore.timing} · {selectedStore.dist}
              </span>
                </div>
                <button className={styles.changeBtn} onClick={() => setSelectedStore(null)}>Change</button>
              </div>
          )}

          {/* ── Offer Banner ── */}
          <div className={styles.offerBanner}>
            <div>
              <p className={styles.offerTag}>EXCLUSIVE OFFER</p>
              <p className={styles.offerHeadline}>10% off your first<br />in-store pickup</p>
              <button className={styles.offerCta}>Claim offer →</button>
            </div>
            <span className={styles.offerEmoji}>🛒</span>
          </div>

          {/* ── Categories ── */}
          <div className={styles.sectionHeader}>
            <h2 className={styles.sectionTitle}>Shop by category</h2>
          </div>
          <div className={styles.catGrid}>
            {CATEGORIES.map(cat => (
                <button
                    key={cat.id}
                    className={`${styles.catCard} ${selectedCat === cat.id ? styles.catCardActive : ''}`}
                    onClick={() => handleSelectCat(cat.id)}
                >
                  <div className={styles.catIconWrap} style={{ background: cat.bg }}>
                    {cat.icon}
                  </div>
                  <p className={styles.catLabel}>{cat.label}</p>
                  <p className={styles.catCount}>{cat.count}</p>
                </button>
            ))}
          </div>

          {/* ── Filter Chips (shown when category selected) ── */}
          {selectedCat && (
              <div className={styles.filtersRow}>
                {FILTERS.map(f => (
                    <button
                        key={f}
                        className={`${styles.filterChip} ${activeFilter === f ? styles.filterChipActive : ''}`}
                        onClick={() => setActiveFilter(f)}
                    >
                      {f}
                    </button>
                ))}
              </div>
          )}

          {/* ── Items Grid ── */}
          <div className={styles.sectionHeader}>
            <h2 className={styles.sectionTitle}>
              {selectedCat
                  ? CATEGORIES.find(c => c.id === selectedCat)?.label
                  : searchQuery && !selectedCat ? `Results for "${searchQuery}"` : 'Featured items'}
            </h2>
          </div>

          {displayedItems.length === 0 ? (
              <div className={styles.emptyState}>
                <p className={styles.emptyIcon}>😶</p>
                <p>No items found. Try a different filter or category.</p>
              </div>
          ) : (
              <div className={styles.itemsGrid}>
                {displayedItems.map(item => (
                    <ItemCard
                        key={item.name}
                        item={item}
                        added={cartItems.has(item.name)}
                        onAdd={handleAddToCart}
                    />
                ))}
              </div>
          )}
        </main>

        {/* ── Cart FAB ── */}
        {cartCount > 0 && (
            <div className={styles.cartFab}>
              🛒 View Cart
              <span className={styles.cartCount}>{cartCount}</span>
            </div>
        )}

        {/* ── Toast ── */}
        <div className={`${styles.toast} ${toastVisible ? styles.toastVisible : ''}`}>
          {toast}
        </div>
      </div>
  );
}
